/* FANUC SRVO alarm codes — generated by tools/fetch-alarms.js,
 * DO NOT EDIT; re-run the tool instead. 297 codes, 2026-10-22.
 * Source: http://linuxsand.info/fanuc/ — internal reference copy, by permission. */
(function (global) {
  var data = {
    "001": "SRVO-001 Operator panel E-stop\nCause:  The EMERGENCY STOP button on the operator panel was pressed.\nRemedy:\n1.  Twist the operator panel EMERGENCY STOP button clockwise to release it, then press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "002": "SRVO-002 Teach pendant E-stop\nCause:  The EMERGENCY STOP button on the teach pendant was pressed.\nRemedy:\n1.  Twist the teach pendant EMERGENCY STOP button clockwise to release it, then press RESET.\n2.  If this alarm cannot be reset, replace the teach pendant.",
    "003": "SRVO-003 Deadman switch released\nCause:  The deadman switch was not pressed when the teach pendant was enabled.\nRemedy:\n1.  Press the deadman switch to release it, then press RESET. If the deadman switch is three position switch type,\npress the deadman switch to middle position to release it, then press RESET.\n2.  If this alarm cannot be reset, replace the teach pendant.",
    "004": "SRVO-004 Fence open\nCause:  The safety door or fence is open.\nRemedy:\n1.  Close the safety fence after checking that a worker is not inside the safe fence, then press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "005": "SRVO-005 Robot overtravel\nCause:  A hardware limit switch on an axis was tripped. Usually, the movement of the robot is prevented from exceeding a\nlimit beyond the maximum range of movement (software limits) for each axis. However, when the robot is shipped,\nthe overtravel state is set for transit.\nRemedy:\n1.  Hold down the SHIFT key, and press RESET to reset the alarm.\n2.  Continue holding the SHIFT key, and jog the robot to bring all axes into the movable range.",
    "006": "SRVO-006 Hand broken\nCause:  A safety hand has broken. If no broken hand can be found, however, the most likely cause is the HBK signal of a robot\nconnection cable being at the 0 V level.\nRemedy:\n1.  Hold down the SHIFT key, and press RESET to reset the alarm.\n2.  While holding down the SHIFT key, jog the tool to the workplace. Replace the safety hand or check the safety\njoint cable. If the Hand broken signal is not in use, it can be disabled in the system config screen / Hand broken\nsetting. After these measures, hold down the SHIFT key, and press RESET.\n3.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "007": "SRVO-007 External emergency stops\nCause:  The external EMERGENCY STOP button was pressed.\nRemedy:\n1.  If you are using the external emergency stop, clear the source of the fault, and press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "009": "SRVO-009 Pneumatic pressure alarm\nCause:  The pneumatic pressure alarm indicates the presence of a defect. If the pneumatic pressure alarm is not detected,\nhowever, the most likely cause is the PPABN signal of a robot connection cable being at the 0 V level.\nRemedy:\n1.  Repair the pneumatic pressure or check the cable.\n2.  If the pneumatic pressure signal is not in use, it can be disabled in the system config screen.\n3.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "010": "SRVO-010 Belt broken\nCause:  The belt broken robot digital input is asserted.\nRemedy:\n1.  If the belt is found to be defective in any way, repair it and then press RESET.\n2.  When the belt is found to be normal, signal RDI [7] in the robot connection cable might be abnormal. Check the\ncable.\nNote: In the robot series whose system variable $PARAM_GROUP.$BELT_ENABLE is TRUE, this alarm is\ndetected.",
    "012": "SRVO-012 Power failure recovery\nCause:  Normal power on (hot start).\nRemedy:  This is just a notification. You do not have to do anything for this warning message.",
    "014": "SRVO-014 Fan motor abnormal (%d), CPU STOP\nCause:  When a fan motor stops on backplane unit, TP shows the following message. In one minutes from occurring of alarm,\nrobot stops and cannot be operated from TP. The robot can be recovered by replacing a fan motor. Number in the\nbracket indicates which fan is abnormal.\n(1): fan above the slot1\n(2): fan above the slot2\n(3): both fans\nRemedy:\n1.  Check the fan motor and its cables. Replace them if necessary.\n2.  Replace the backplane unit.\nBefore executing the remedy 3, perform a complete controller back up as image to save all your programs and settings.\n3.  Replace the main board, and restore the image backup.\nRefer to the Controller Maintenance Manual for more information.",
    "015": "SRVO-015 System over heat\nCause:  The temperature of the controller is higher than the specified value. In one minutes from occurring of alarm, robot\nstops and cannot be operated from TP.\nRemedy:\n1.  If the ambient temperature is higher than specified (45°C), cool down the ambient temperature.\n2.  If the fan motor is not running, check it and its cables. Replace them if necessary.\nBefore executing the remedy 3, perform a complete controller back up as image to save all your programs and settings.\n3.  Replace the main board, and restore the image backup. (The thermostat on the main board may be faulty.)\nRefer to the Controller Maintenance Manual for more information.",
    "018": "SRVO-018 Brake abnormal (G:%d A:%d)\nCause:  The brake current exceeded the specification.\nRemedy:  There is possibility that the robot connection cable might short. Refer to the Controller Maintenance Manual for more\ninformation.",
    "021": "SRVO-021 SRDY off (Group:%d Axis:%d)\nCause:  The ready signal of the servo amplifier corresponding to the displayed group and axis was turned off.\nRemedy:\n1.  Refer to those cause/measures when the alarm history is confirmed and other alarms have occurred at the same\ntime.\n2.  If this alarm occurred after add axis or modification of axis setup, confirm whether a set content is correct. If the\nmistake is found, modify it. Especially, confirm whether to find the mistake in the FSSB line number, the\nhardware start axis, the amplifier number, and the amplifier type.\n3.  Confirm the setting of the machine lock for the multi group.\n•  Advance to measures 4 when all mo tion groups machine lock are released.\n•  Release the machine lock of  the robot when the robot (6-axis amplifier) is a machine lock.\n4.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.\nNote:\n1.  When 6-axis amplifier is made a machine lock, the amplifier subordinate to this turns off and SRDY is turned\noff.\n2.  There is a possibility when the specification of the teach pendant is not correct compared with the controller. For\ninstance, when the teach pendant of the RIA/CE specification is used in the controller of non-RIA/CE\nspecification, this alarm might occur. Connect the correct teach pendant corresponding to the controller.",
    "022": "SRVO-022 SRDY on (Group:%d Axis:%d)\nCause:  SRDY was already on when an attempt was made to turn on the MCC with HRDY. (HRDY is the signal sent from the\nhost to the servo system to specify whether to turn the servo amplifiers MCC on or off. SRDY is the signal sent from\nthe servo system to the host to indicate whether a servo amplifiers MCC is on or off.)\nRemedy:\n1.  Replace the servo amplifier applicable to the alarm message.\n2.  Replace the servo card module or the auxiliary axis board applicable to the alarm message.",
    "023": "SRVO-023 Stop error excess(G:%d A:%d)\nCause:  When the robot stopped, the servo positional error exceeded a specified value ($PARAM_GROUP.$STOPERLIM).\nThis alarm means that the robot cannot reach a taught point or cannot keep a taught posture. Probable causes:\n1. Overload\n2.  External force to the robot\n3.  Disconnection or misconnection of the motor power cable or brake cable\n4.  Incorrect setup for the robot which has 2 axis brake option\n5.  Insufficient torque by low voltage of power supply\n6.  Brake failure (includes mis-setting of brake number for auxiliary axis)\n7.  Aux. brake unit failure for aux. axis\n8. Amplifier failure\n9. Motor failure\n10.  Motor power cable or brake cable failure\nRemedy:\n1.  Check whether the duty and applied load exceed the rating. If so, reduce the duty or applied load.",
    "024": "SRVO-024 Move error excess(G:%d A:%d)\nCause:  When the robot moved, the servo positional error exceeded a specified value ($PARAM_GROUP.$MOVER_OFFST).\nThis alarm means that the excessive path deviation occurs. Probable cause: Same as described above (SRVO-023).\nRemedy:  Perform the same action as that described for the previous item (SRVO-023). However, it does not relate to the brake\noption setting in this case.",
    "025": "SRVO-025 Motn dt overflow (G:%d A:%d)\nCause:  The motion command is too large.\nRemedy:\n1.  Perform a Cold start\n•  Turn off the robot.\n•  On the teach pendant, press and hold the SHIFT and RESET keys.\n•  While still pressing the SHIFT a nd RESET keys, turn on the robot.\n2.  If the error is not cleared, document the events that led to the error and contact your FANUC technical\nrepresentative.",
    "026": "SRVO-026 Motor speed limit(G:%d A:%d)\nCause:  An attempt was made to exceed the maximum rated motor speed ($PARAM_GROUP.$MOT_SPD_LIM). The motor\nspeed is clamped to its maximum rated value.\nRemedy:  This is just a notification. However, you should attempt to eliminate this error and not rep eat the circumstances that led\nup to it.",
    "027": "SRVO-027 Robot not mastered(Group:%d)\nCause:  An attempt was made to perform calibration, but mastering has not yet been completed.\nRemedy:  Perform mastering from the calibration screen [6 SYSTEM Master/Cal].",
    "030": "SRVO-030 Brake on hold (Group:%d)\nCause:  When the Brake On Hold function is enabled, this alarm is issued whenever a hold signal is input.\nRemedy:\n1.  This is just a notification. You do not have to do anything for this message.\n2.  If you do not use this function, disable [Brake On Hold] on the general item setting screen [6 SETUP General]\nand perform a power cycle.",
    "031": "SRVO-031 User servo alarm (Group:%d)\nCause:  A user servo alarm was issued. This alarm is occurred when system variable $MCR_GRP.$SOFT_ALARM is set to\nTRUE.\nRemedy:  Confirm why $MCR_GRP.$SOFT_ALARM is set to to TRUE.",
    "033": "SRVO-033 Robot not calibrated(Grp:%d)\nCause:  An attempt was made to set a reference point for quick mastering, but calibration has not yet been completed.\nRemedy:  Perform calibration by following the procedure below.\n1.  Turn on the power.\n2.  Execute [CALIBRATION] from the calibration screen [6 SYSTEM Master/Cal].",
    "034": "SRVO-034 Ref pos not set (Group:%d)\nCause:  An attempt was made to perform quick mastering, but a required reference point has not yet been set.\nRemedy:  Set a reference point for quick mastering from the calibration screen.",
    "035": "SRVO-035 Joint speed limit(G:%d A:%d)\nCause:  A value higher than the maximum axis speed ($PARAM_GROUP.$JNTVELLIM) was specified. Each actual axis\nspeed is tied to the maximum speed.\nRemedy:  Decrease the axis speed value to be within limit specified in ($PARAM_GROUP.$JNTVELLIM).",
    "036": "SRVO-036 Inpos time over (G:%d A:%d)\nCause:  The in-position monitor time ($PARAM_GROUP.$IMPOS_TIME) has elapsed, but the robot cannot reach a taught\npoint within the specified in-position ($PARAM_GROUP.$STOPTOL).\nRemedy:  Perform the same action as that described for SRVO-023 (Stop error excess).",
    "037": "SRVO-037 IMSTP input (Group:%d)\nCause:  The *IMSTP signal, which is a peripheral device I/O signal, is OFF.\nRemedy:  Turn on the *IMSTP signal.",
    "038": "SRVO-038 Pulse mismatch (G:%d A:%d)\nCause:  A pulse count detected at power-on differs from one detected at power-off. This could be due to the following:\n1.  File (SYSMAST.SV) that saved in the state at an axis position different from a present axis position was loaded.\n2.  The software brake setting is incorrect.\n3.  A incorrect brake type was set to the robot with two-axis brake option.\n4.  File (SYSMAST.SV) that saved with other robots was loaded.\n5.  The axis position was changed with a brake release unit while the controller power is off.\n6.  The axis fell while the controller power is off due to the brake trouble.\nRemedy:\n1.  Refer SRVO-222 when this error occurs with SRVO-222.\n2.  For the above cause 2 and 3, confirm the setup or brake type setting and correct setting. For the above cause 4,\nre-load SYSMAST.SV of the robot. Afterwards, PULSE RESET operation should be done. There are the\nfollowing two methods.\n•  Method 1: Move the cursor to $MCR.$SPC_RESET on the  system variable screen, and select F4 TRUE. It\nbecomes TRUE momentarily, it writes in FALSE at once. Then press RESET.\n•  Method 2: F3 RES_PCA is pushed on the MASTER/CAL  screen, and select F4 YES. Then press RESET.\nNote: The MASTER/CAL screen is not usually displayed. The worker who has the operation qualification does. Check\nwhether the robot position on Teach Pendant is correct. If incorrect, re-mastering is required.",
    "039": "SRVO-039 Motor speed excess(G:%d A:%d)\nCause:  CMC cannot work because the calculated motor speed exceeded the specification.\nRemedy:  Reduce the motion speed or disable CMC.",
    "041": "SRVO-041 MOFAL alarm (Grp:%d Ax:%d)\nCause:  A value of the internal motion command is too big.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.",
    "043": "SRVO-043 DCAL alarm(Group:%d Axis:%d)\nCause:  The energy produced by regenerative discharge is excessive. As a result, all the generated energy cannot be dissipated\nas heat.\nRemedy:\n1.  This alarm may occur if the axis is subjected to frequent acceleration/deceleration or if the axis is vertical and\ngenerates a large amount of regenerative energy. If this alarm has occurred, relax the conditions.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "044": "SRVO-044 DCHVAL alarm (PS) (Group:%d Axis:%d)\nCause:  The DC voltage (DC link voltage) of the main circuit power supply is abnormally high.\nRemedy:  Refer to the Controller Maintenance Manual.",
    "045": "SRVO-045 HCAL alarm(Group:%d Axis:%d)\nCause:  An excessively high current flowed through the main circuit of the servo amplifier.\nRemedy:  Turn off the controller power, and disconnect the power cable  from the servo amplifier indicated by the alarm message.\nAlso disconnect the brake cable to avoid the axis falling unexpectedly.\n1.  In the above condition, supply controller power again and check if this alarm occurs again. If this alarm occurs\nagain, replace the servo amplifier.\n2.  About the power cable, check the insulation of their U, V, W and the GND lines each other. If there is a\nshort-circuit, replace the power cable.\n3.  About the power cable, measure the resistance between their U and V, V and W, and W and U with an ohmmeter\nthat has a very low resistance range. If the resistances at the three places are different from each other, the motor,\nthe power cable is defective. Check each item in detail and replace it if necessary.\nRefer to the Controller Maintenance Manual for more information.",
    "046": "SRVO-046 OVC alarm (Group:%d Axis:%d)\nCause:  The root-mean-square current value which is calculated internally by the servo system exceeds the maximum\npermissible value. This alarm is issued to protect the motor and amplifier from damage of thermal destruction.\nProbable cause:\n1. Overload\n2.  External force to the robot\n3.  Disconnection of the brake cable\n4.  Insufficient torque by low voltage of power supply\n5.  Brake failure (includes mis-setting of brake number for auxiliary axis)\n6.  Aux. brake unit failure for aux. axis\n7. Amplifier failure\n8. Motor failure\n9.  Motor power cable or brake cable failure\nRemedy:\n1.  Check whether the duty and applied load exceed the rating. If so, reduce the duty or applied load.\n2.  Check whether the robot is pushed or pulled by external force. If so, remove the external force to the robot or\nmodify the taught point.\n3.  Check whether the brake cable/connector are connected correctly.\n4.  Measure the supplied voltage. Then, check whether the voltage is matched to the controller specification.\n5.  Check whether the motor brake is released properly when Reset or the robot moves. First of all, check whether\nthe setting of brake number is correct when this alarm occurs on auxiliary axis.\n6.  When this alarm occurs on the auxiliary axis which brake is controlled by the aux. brake unit, check the fuse on\nthe aux. brake unit.\n7.  If this alarm cannot be reset, the troubles of related parts are thought. Refer to the Controller Maintenance\nManual for more information. About auxiliary axis, refer to the Auxiliary Axis Option Maintenance Manual.",
    "047": "SRVO-047 LVAL alarm(Group:%d Axis:%d)\nCause:  The control power supply voltage to servo amplifier is excessively low.\nRemedy:  There is possibly trouble with the servo amplifier and/or the power supply unit. Refer to the Controller Maintenance\nManual for more information.",
    "049": "SRVO-049 OHAL1 alarm (Grp:%d Ax:%d)\nCause:  The thermostat in the transformer worked.\nRemedy:  Refer to the Controller Maintenance Manual.",
    "050": "SRVO-050 Collision Detect alarm (G:%d A:%d)\nCause:  A collision was detected. (An excessively large disturbance torque was estimated by the servo software.) Probable\ncauses are:\n1.  Collision (Tip stick) / External force to the robot\n2.  Overload / Heavy acceleration\n3.  Increasing of the friction by low temperature\n4.  Insufficient torque by low voltage of power supply\n5.  Brake failure (includes mis-setting of brake number for auxiliary axis)\n6.  Aux. brake unit failure for aux. axis\n7. Amplifier failure",
    "051": "SRVO-051 CUER alarm(Group:%d Axis:%d)\nCause:  The offset of the current feedback value is excessively large. Current detection circuit failure is in the amplifier.\nRemedy:  Replace the servo amplifier.",
    "053": "SRVO-053 Disturbance excess(G:%d A:%d)\nCause:  Disturbance estimated in the software exceeds the threshold value. There is a possibility that SRVO-050 occurs when\nthe robot runs leaving this warning.\nRemedy:\n1.  Check whether the payload (mass, center of gravity, and inertia) are set correctly.\n2.  Check whether the applied load exceed the rating. If so, reduce the applied load.\n3.  If this alarm occurs when the robot is used after long time interval or when the temperature is very low, run the\nrobot with low speed for a while before running with normal speed.",
    "055": "SRVO-055 FSSB com error 1 (G:%d A:%d)\nCause:  A communication error has occurred between the main board and the servo amplifier. (from main board to servo\namplifier.)\nRemedy:  Refer to the Controller Maintenance Manual. About auxiliary axis, refer to the Auxiliary Axis Option Maintenance\nManual.",
    "056": "SRVO-056 FSSB com error 2 (G:%d A:%d)\nCause:  A communication error has occurred between the main board and servo amplifier. (from servo amplifier to main\nboard.)\nRemedy:  Refer to the Controller Maintenance Manual. About auxiliary axis, refer to the Auxiliary Axis Option Maintenance\nManual.",
    "057": "SRVO-057 FSSB disconnect (G:%d A:%d)\nCause:  Communication was interrupted between the main board and the servo amplifier.\nRemedy:  Refer to the Controller Maintenance Manual. About auxiliary axis, refer to the Auxiliary Axis Option Maintenance\nManual.",
    "058": "SRVO-058 FSSB %d init error (%d)\nCause:  FSSB initializing is failed.\nRemedy:  Refer to the Controller Maintenance Manual. Note: Need power cycle to release this alarm.",
    "059": "SRVO-059 Servo amp init error\nCause:  Servo amplifier initializing has failed.\nRemedy:  Check the servo amplifier and its wiring. Refer to the Controller Maintenance Manual for more information.\nNote: Need power cycle to release this alarm.",
    "061": "SRVO-061 CKAL alarm(Group:%d Axis:%d)\nCause:  The clock for the rotation counter in the Pulsecoder is abnormal.\nRemedy:  Replace the Pulsecoder. After replacing, perform mastering.\nNote: If this alarm occurs along with a SRVO-068 DTERR, SRVO-069 CRCERR, or SRVO-070 STBERR, disregard\nthis alarm and refer to the other three alarm remedies.",
    "062": "SRVO-062 BZAL alarm(Group:%d Axis:%d)\nCause:  This alarm is issued when the battery for backing up the absolute position data of the Pulsecoder is not connected or is\nempty. The battery cable inside the robot might have become disconnected.\nRemedy:  Replace the battery in the battery box of the robot base or the Pulsecoder. Refer to the Controller Maintenance Manual\nfor more information.\nCorrect the cause of the alarm, then turn on the power again after doing PULSE RESET operation. Mastering is\nrequired. There are the following two methods for PULSE RESET.\nMethod 1: Move the cursor to $MCR.$SPC_RESET on the system variable screen, and select F4 TRUE. It\nbecomes TRUE momentarily, it writes in FALSE at once. Then press RESET.\nMethod 2: F3 RES_PCA is pushed on the MASTER/CAL screen, and select F4 YES. Then press RESET.\nNote: The MASTER/CAL screen is not usually displayed.",
    "063": "SRVO-063 RCAL alarm(Group:%d Axis:%d)\nCause:  The built-in rotation counter on the Pulsecoder is abnormal.\nRemedy:\n1.  Replace the Pulsecoder.\n2.  After replacing, set the system variable $MCR.$SPC_RESET to TRUE, and turn the power off and then on\nagain.\n3.  Master the robot.\nNote: If this alarm occurs along with a SRVO-068 DTERR, SRVO-069 CRCERR, or SRVO-070 STBERR, disregard\nthis alarm and refer to the other three alarm remedies.",
    "064": "SRVO-064 PHAL alarm(Group:%d Axis:%d)\nCause:  This alarm is issued when the phase of a pulse signal generated by the Pulsecoder is abnormal.\nRemedy:  Replace the Pulsecoder. After replacing, perform mastering.\nNote: If this alarm occurs along with a SRVO-068 DTERR, SRVO-069 CRCERR, or SRVO-070 STBERR, disregard\nthis alarm and refer to the other three alarm remedies.",
    "065": "SRVO-065 BLAL alarm(Group:%d Axis:%d)\nCause:  The battery voltage for the Pulsecoder has dropped below the allowable minimum.\nRemedy:  Replace the battery.\nNote: When this alarm is issued, immediately replace the battery while the system power is turned on. If the BZAL\nalarm is issued because the battery is not replaced in time, position data will be lost, thus necessitating robot\nmastering.",
    "066": "SRVO-066 CSAL alarm(Group:%d Axis:%d)\nCause:  The Pulsecoder ROM checksum data is abnormal.\nRemedy:  Replace the Pulsecoder. After replacing, perform mastering.\nNote: If this alarm occurs along with a SRVO-068 DTERR, SRVO-069 CRCERR, or SRVO-070 STBERR, disregard\nthis alarm and refer to the other three alarm remedies.",
    "067": "SRVO-067 OHAL2 alarm (Grp:%d Ax:%d)\nCause:  The temperature inside the Pulsecoder has become too high, causing the built-in thermostat to actuate.",
    "068": "SRVO-068 DTERR alarm (Grp:%d Ax:%d)\nCause:  A request signal was sent to the serial Pulsecoder, but no serial data was returned.\nRemedy:\n1.  Check the connection of the cable between the Pulsecoder and servo amplifier. (If the alarm is occurred at robot\naxes, check the connection of the robot interconnection cable (for the Pulsecoder)).\n2.  Check the shielding of the above cable is connected securely to the grounding plate.\n3.  Replace the Pulsecoder.\n4.  Replace the servo amplifier.\n5.  Replace the robot interconnection cable (for the Pulsecoder).\nRefer to the Controller Maintenance Manual for more information.",
    "069": "SRVO-069 CRCERR alarm (Grp:%d Ax:%d)\nCause:  Serial data changed during transfer.\nRemedy:  Refer to the SRVO-068 Remedy.",
    "070": "SRVO-070 STBERR alarm (Grp:%d Ax:%d)\nCause:  A serial data start bit or stop bit error occurred.\nRemedy:  Refer to the SRVO-068 Remedy.",
    "071": "SRVO-071 SPHAL alarm (Grp:%d Ax:%d)\nCause:  The excessively large feedback speed was detected.\nRemedy:\n1.  This alarm does not indicate the main cause of the problem if issued together with the PHAL alarm (SRVO-064).\n2.  It might be mis-detection by the noise. Check whether the ground/shield is connected correctly. If possible,\nenhance the ground/shield.\n3.  Replace the Pulsecoder of the motor. Mastering is required.\n4.  Replace the servo amplifier.\n5.  Replace the robot connection cable.\n6.  Replace the cable in the mechanical unit.",
    "072": "SRVO-072 PMAL alarm(Group:%d Axis:%d)\nCause:  The Pulsecoder might be faulty.\nRemedy:  Replace the Pulsecoder, then perform mastering.",
    "073": "SRVO-073 CMAL alarm(Group:%d Axis:%d)\nCause:  The Pulsecoder may be faulty, or noise may be causing the Pulsecoder to malfunction.\nRemedy:\n1.  Improve the shielding.\n2.  Do PULSE RESET Operation.\n3.  Replace the Pulsecoder, then perform mastering.\nRefer to the Controller Maintenance Manual for more information.",
    "074": "SRVO-074 LDAL alarm(Group:%d Axis:%d)\nCause:  The LED on the Pulsecoder has become disconnected.\nRemedy:  Replace the Pulsecoder, then perform mastering.",
    "075": "SRVO-075 Pulse not established(G:%d A:%d)\nCause:  The absolute position of the Pulsecoder has not yet been established. This alarm appears normally after BZAL or\nCMAL.\nRemedy:  Reset the alarm, and jog the axis on which the alarm has occurred until the same alarm does not occur again. (Jog one\nmotor revolution). This alarm must be cleared before mastering.",
    "076": "SRVO-076 Tip Stick Detection(G:%d A:%d)\nCause:  An excessive disturbance was calculated in the servo software at the beginning of motion. (An abnormal load was\ndetected. The cause might be welding.)\nRemedy:  Perform the same action as that described for SRVO-050 (CLALM alarm).\nNote: The threshold level for the tip stick detection cannot be changed from STATUS/Axis/Disturb screen.",
    "078": "SRVO-078 Servo param update(G:%d A:%d)\nCause:  The servo parameter has been updated.\nRemedy:  Press RESET and continue.",
    "079": "SRVO-079 Stroke exceeded during press(G:%d A:%d)\nCause:  The gun tip position during the pressuring operation (SPOT or PRESS_MOTN) exceeded the stroke limit for the gun.\nThe squeezing operation stopped because the gun axis had over-extended.\nRemedy:  Check the master position and close stroke limit for the gun. If these values are incorrect, then update them. If these\nvalues are correct, then install new tips so that the gun can operate within the stroke limits, during pressuring.",
    "081": "SRVO-081 EROFL alarm (Track enc:%d)\nCause:  The pulse count for the line tracking encoder (incremental Pulsecoder) has overflowed.\nRemedy:\n1.  Reduce the encoder speed (conveyor speed).\n2.  Replace the incremental Pulsecoder for the line tracking.\n3.  Replace the line tracking cable.\n4.  Replace the line tracking I/F board.",
    "082": "SRVO-082 DAL alarm(Track encoder:%d)\nCause:  The line tracking Pulsecoder has not been connected.\nRemedy:\n1.  Check the connection cable at each end (the line tracking I/F board and the Pulsecoder).\n2.  Check whether the shielding of the connection cable is connected securely to the grounding plate.\n3.  Replace the line tracking cable.\n4.  Replace the Pulsecoder.\n5.  Replace the line tracking I/F board.",
    "083": "SRVO-083 CKAL alarm (Track enc:%d)\nCause:  The clock for the rotation counter in the Pulsecoder is abnormal.\nRemedy:  See the description for the SRVO-061 CKAL alarm.",
    "084": "SRVO-084 BZAL alarm (Track enc:%d)\nCause:  This alarm is issued when the battery for backing up the absolute position data for the Pulsecoder is not connected.\nRemedy:  See the description for the SRVO-062 BZAL alarm.",
    "085": "SRVO-085 RCAL alarm (Track enc:%d)\nCause:  The built-in rotation counter on the Pulsecoder is abnormal.\nRemedy:  See the description for the SRVO-063 RCAL alarm.",
    "086": "SRVO-086 PHAL alarm (Track enc:%d)\nCause:  This alarm is issued when the phase of a pulse signal generated by the Pulsecoder is abnormal.\nRemedy:  See the description for the SRVO-064 PHAL alarm.",
    "087": "SRVO-087 BLAL alarm (Track enc:%d)\nCause:  This alarm is issued when the battery voltage for backing up the absolute position data of the Pulsecoder has dropped\nbelow the allowable minimum.\nRemedy:  See the description for the SRVO-065 BLAL alarm.",
    "088": "SRVO-088 CSAL alarm (Track enc:%d)\nCause:  The Pulsecoder ROM checksum data is abnormal.\nRemedy:  See the description for the SRVO-066 CSAL alarm.",
    "089": "SRVO-089 OHAL2 alarm (Track enc:%d)\nCause:  The motor has overheated.\nRemedy:  See the description for the SRVO-067 OHAL2 alarm.",
    "090": "SRVO-090 DTERR alarm (Track enc:%d)\nCause:  An error occurred during communication between the Pulsecoder and the line tracking I/F board.\nRemedy:\n1.  Check the connection cable at each end (the line tracking I/F board and the Pulsecoder).\n2.  Check whether the shielding of the connection cable is connected securely to the grounding plate.\n3.  Replace the line tracking cable.\n4.  Replace the Pulsecoder.\n5.  Replace the line tracking I/F board.",
    "091": "SRVO-091 CRCERR alarm (Track enc:%d)\nCause:  An error occurred during communication between the Pulsecoder and the line tracking I/F board.\nRemedy:  Refer to the SRVO-090 Remedy.",
    "092": "SRVO-092 STBERR alarm (Track enc:%d)\nCause:  An error occurred during communication between the Pulsecoder and the line tracking I/F board.\nRemedy:  Refer to the SRVO-090 Remedy.",
    "093": "SRVO-093 SPHAL alarm (Track enc:%d)\nCause:  An excessive speed was detected with the line tracking encoder.\nRemedy:\n1.  This alarm does not indicate the main cause of the problem if issued together with the PHAL alarm(SRVO-086).\nRefer to SRVO-086.\n2.  Reduce the encoder speed (conveyor speed).\n3.  Check whether the shield of the line tracking cable is connected to earth bar in the controller.\n4.  Replace the absolute Pulsecoder for the line tracking.\n5.  Replace the line tracking cable.\n6.  Replace the line tracking I/F board.",
    "094": "SRVO-094 PMAL alarm (Track enc:%d)\nCause:  The Pulsecoder might be faulty.\nRemedy:  See the description for the SRVO-072 PMAL alarm.",
    "095": "SRVO-095 CMAL alarm (Track enc:%d)\nCause:  It is likely that the Pulsecoder is abnormal or the Pulsecoder has malfunctioned due to noise.\nRemedy:\n1.  Reinforce the earth of the flange of the motor.\n2.  Replace the Pulsecoder.",
    "096": "SRVO-096 LDAL alarm (Track enc:%d)\nCause:  The LED on the Pulsecoder has become disconnected.\nRemedy:  See the description for the SRVO-074 LDAL alarm.",
    "097": "SRVO-097 Pulse not established(Enc:%d)\nCause:  The absolute position of the Pulsecoder has not yet been established.\nRemedy:  See the description for the SRVO-075 Pulse not established.",
    "098": "SRVO-098 ACC sensor DTERR alarm\nCause:  The acceleration sensor has not been connected. Otherwise, an error occurred during communication between the\nacceleration sensor and the main board.\nRemedy:\n1.  Check connection of the connector of the connecting cable.\n2.  Check the shielding of the above cable is connected securely to the grounding plate.\n3.  Replace the above cable.\n4.  Replace the acceleration sensor.",
    "099": "SRVO-099 ACC sensor CRCERR alarm\nCause:  Data changed during transfer from the acceleration sensor.\nRemedy:  Refer to the SRVO-098 Remedy.",
    "100": "SRVO-100 ACC sensor STBERR alarm\nCause:  A stop bit error of the data from the acceleration sensor occurred.\nRemedy:  Refer to the SRVO-098 Remedy.",
    "101": "SRVO-101 Robot overtravel(Group:%d)\nCause:  A Robot overtravel limit switch has been pressed.\nRemedy:  Refer to the SRVO-005 Remedy.",
    "102": "SRVO-102 Hand broken (Group:%d)\nCause:  The hand broken (*HBK) robot input is asserted.\nRemedy:  Refer to the SRVO-006 Remedy.",
    "103": "SRVO-103 Air pressure alarm(G:%d)\nCause:  The pneumatic pressure (PPABN) robot input is asserted.\nRemedy:  Refer to the SRVO-009 Remedy.",
    "105": "SRVO-105 Door open or E.Stop\nCause:\n1.  The controller door is opened or the emergency stop signals are detected for a short time.\n2.  The specification of the teach pendant is not correct compared with the controller.\nRemedy:\n1.  Close the controller door, and press RESET.\n2.  Check the specification of the teach pendant is not correct compared with the controller. For instance, the teach\npendant of the RIA/CE specification is used in the controller of non-RIA/CE specification, this alarm might\noccur. Connect the teach pendant corresponding to the controller.\n3.  Refer to the Controller Maintenance Manual for more information.",
    "106": "SRVO-106 Door open/E.Stop(Robot:%d)\nCause:\n1.  The controller door is opened or the emergency stop signals are detected for a short time.\n2.  The specification of the teach pendant is not correct compared with the controller.\nRemedy:  See the description for the SRVO-105 Door open or E.Stop.",
    "108": "SRVO-108 ACC sensor livecode error\nCause:  The error may have occurred in communication of the force sensor.\nRemedy:  See the error message about the force sensor.",
    "109": "SRVO-109 ACC sensor ID mismatch %d\nCause:\n1.  The acceleration sensor has not been connected.\n2.  A sensor other than acceleration sensor is detected.\nRemedy:\n1.  Check connection of the connector of the connecting cable.\n2.  Check the shielding of the above cable is connected securely to the grounding plate.\n3.  Replace the above cable.\n4.  Replace the acceleration sensor.\nBefore executing the remedy 5, perform a complete controller back up as image to save all your programs and settings.\n5.  Replace the main board, and restore the image backup.",
    "111": "SRVO-111 Softfloat time out(G:%d)\nCause:  Follow-up time is over when softfloat is OFF. (When $SFLT_ERRTYP=0)",
    "112": "SRVO-112 Softfloat time out(G:%d)\nCause:  Follow-up time is over when softfloat is OFF. (When $SFLT_ERRTYP=1)\nRemedy:  See the description for the SRVO-111 Softfloat time out.",
    "113": "SRVO-113 Cart. error excess(G:%d %s)\nCause:  While Cartesian Softfloat is being executed, the position error on the rectangular coordinates becomes greater than the\ntolerance that is set by the user.\nRemedy:  Find and remove the cause of the position error becoming greater. Or, make the tolerance larger, turn off and then turn\non the controller. The tolerance is the value of the following system variables.\nX direction [mm] : $PARAM_GROUP.$CB_IX\nY direction [mm] : $PARAM_GROUP.$CB_IY\nZ direction [mm] : $PARAM_GROUP.$CB_IZ",
    "114": "SRVO-114 Singularity Detected\nCause:  A singularity was detected during robot motion.\nRemedy:  Re-teach the program points, use WJNT, or use JOINT MOTYPE.",
    "115": "SRVO-115 Limit error (G:%d, A:%s)\nCause:  The linear path passes outside of the axis limit.\nRemedy:  Re-teach program points, or use JOINT MOTYPE.",
    "116": "SRVO-116 Axis Limit Exceeded (G:%d A:%d)\nCause:  One or more of the robot axes have exceeded an axis soft limit while executing SOFFLOAT.\nRemedy:  Jog the robot within the limits to resume. Adjust the program or process to keep robot axes within limits, or increase\nthe axis limits.",
    "117": "SRVO-117 Brake Number Conflict\nCause:  Machine lock has been set on a group that is using the same brake number as a different group that is not machine\nlocked.\nRemedy:\n1.  Set machine lock for all groups using the common brake.\n2.  Change brake connections so the same brake number is not used by different groups.",
    "118": "SRVO-118 SFIGET err %s\nCause:  This error indicates that an error occurs during SFIGET execution.\nRemedy:  Perform an action according to the number that is displayed in the alarm message.\n5: The schedule number is not specified or abnormal schedule number other than 1~10 integral value is specified.\nSpecify the correct softfloat schedule number with SFIGET.\n1,2,3,4: This error indicates that the software internal error occurs during SFIGET execution. Document the events that\nled to the error, and contact your FANUC technical representative.",
    "119": "SRVO-119 OVR not 100%\nCause:  The override is not 100% when execute SFIGET program.\nRemedy:  Set override 100% and re-execute SFIGET program again.",
    "120": "SRVO-120 SFIVAL abnml (Scd:%d G:%d A:%d)\nCause:  The difference between the integrator torque just before soft float execution starts and $SFLT_GRP. $SFLT_IVAL\nexceeded a specified value ($SFLT_GRP. $SFIVALLIM).\nRemedy:  Execute SFIGET program again, or make $SFLT_GRP. $SFIVALLIM larger.",
    "121": "SRVO-121 Excessive acc/dec time(G:%d)\nCause:  Acceleration time is too long.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.",
    "122": "SRVO-122 Bad last ang(internal)(G:%d)\nCause:  The last angle update request does not match the current angle.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.",
    "123": "SRVO-123 Fan motor rev slow down(%d)\nCause:  The rotation speed of fan motor on backplane unit is slow down. Number in the bracket indicates which fan is\nabnormal.\n(1): fan above the slot1\n(2): fan above the slot2\n(3): both fans\nRemedy:\n1.  Check the fan motor and its cables. Replace them if necessary.\n2.  Replace the backplane unit.\nBefore executing the remedy 3, perform a complete controller back up as image to save all your programs and settings.\n3.  Replace the main board, and restore the image backup.\nRefer to the Controller Maintenance Manual for more information.\nNote: If SRVO-014 appears after SRVO-123, refer SRVO-014.",
    "124": "SRVO-124 Check HardStop if Hit(G:%d A:%d)\nCause:  If SRVO-024 Move Error excess Alarm occurs and the group is not calibrated, this alarm is posted too.\nRemedy:  Refer to the Remedy of SRVO-024.",
    "125": "SRVO-125 Quick stop speed over (G:%d)\nCause:  The quick stop speed is too high.\nRemedy:  Reduce the speed when a quick stop is executed.",
    "126": "SRVO-126 Quick stop error (G:%d)\nCause:  The program was over during the process of quick stop.\nRemedy:  Press RESET.",
    "130": "SRVO-130 OHAL1(PS) alarm (G:%d A:%d)\nCause:  Heat sink temperature of the main circuit of the Power Supply (α iPS) is abnormally high.\nRemedy:\n1.  Check the rotation of the cooling fan of the Power Supply (α iPS).\n2.  Decrease the duty cycle of operation.\n3.  Replace the Power Supply (α iPS).",
    "131": "SRVO-131 LVAL(PS) alarm(G:%d A:%d)\nCause:  Control supply voltage in the Power Supply (α iPS) is abnormally low.\nRemedy:\n1.  Replace the Power Supply (α iPS).\n2.  Replace the servo amplifier.\n3.  Replace the Power Supply Unit.",
    "133": "SRVO-133 FSAL(PS) alarm (G:%d A:%d)\nCause:  The cooling fan for the Control circuit of the Power Supply (α iPS) stopped.\nRemedy:\n1.  Check the status of the cooling fan. And replace it if it was abnormal.\n2.  Replace the Power Supply (α iPS).",
    "134": "SRVO-134 DCLVAL(PS) alarm (G:%d A:%d)\nCause:  The DC voltage (DC link voltage) of the main circuit power supply for the servo amplifier is abnormally low.\nRemedy:\n1.  Verify that the input voltage to the controller is within the rated voltage, and not an open-phase. Verify that the\ntransformer setting is correct.\n2.  It is possible that an instant disconnection of power source causes this alarm. Check whether an instant\ndisconnection occurred.",
    "135": "SRVO-135 FSAL alarm (G:%d A:%d)\nCause:  The cooling fan for the Control circuit stopped.\nRemedy:\n1.  Replace the internal fan motor of the auxiliary servo amplifier that is indicated by the alarm message.\n2.  Replace the servo amplifier that is indicated by the alarm message.",
    "136": "SRVO-136 DCLVAL alarm (G:%d A:%d)\nCause:  The DC voltage (DC link voltage) of the main circuit power supply for the servo amplifier (α iSV) is abnormally low.\nRemedy:\n1.  Check whether the servo amplifier (α iSV) is installed correctly.\n2. Replace the servo amplifier that is indicated by the alarm message.",
    "138": "SRVO-138 SDAL alarm (G:%d A:%d)\nCause:  A Pulsecoder signal error was detected by the software. The probable cause is noise or a failure (disconnection) in the\nPulsecoder internal circuit.\nRemedy:\n1.  If a normal operation can be resumed by turning the controller power off and on again, it is likely that the cause\nis noise. Enhance the shielding of the Pulsecoder cable.\n2.  If a normal operation cannot be resumed by cycle power, the Pulsecoder is defective. Replace it, and perform\nmastering.",
    "156": "SRVO-156 IPMAL alarm (G:%d A:%d)\nCause:  Abnormally high current flowed through the main circuit of the servo amplifier.\nRemedy:  Refer to the remedy of SRVO-045.",
    "157": "SRVO-157 CHGAL(PS) alarm (G:%d A:%d)\nCause:  The charge of the capacitor of DC link voltage on the servo amplifier could not finish within specified time.\nRemedy:  Refer to the Controller Maintenance Manual for more information.",
    "170": "SRVO-170 Lack of DSP (ID:%d)\nCause:  The number of DSPs on the axis card is lacking.\nRemedy:\n1.  Check the software axis config (FSSB line number).\n2.  Replace the axis card with a card has enough DSPs for your system.\n3.  Add an auxiliary axis board.",
    "171": "SRVO-171 MotorSpd lim/DVC(G:%d A:%d)\nCause:  The motor can not rotate as fast as the calculated speed required for the current motion.\nRemedy:  N/A.",
    "179": "SRVO-179 Motor torque limit(G:%d A:%d)\nCause:  The torque of the axis has exceeded the limit.\nRemedy:  N/A.",
    "180": "SRVO-180 Control axis not exist\nCause:  Controllable axis does not exist on any group.\nRemedy:  Execute aux axis setting to add axis at controlled start.\nNote: Perform a power cycle to release this alarm.",
    "182": "SRVO-182 Needed init. has not been done\nCause:  This is an error internal to the system. A system variable or internal work memory has not been initialized normally.\nRemedy:",
    "183": "SRVO-183 ROBOT isnt ready\nCause:  The servo is off.\nRemedy:  Remove the factor that turned servo off, and press RESET.",
    "184": "SRVO-184 Other task is processing\nCause:  The data area that this instruction tried to use had been locked by another task.\nRemedy:\n1.  If this alarm is occurred when the Payload Estimation is restarted, execute the Payload Estimation after it waits\nfor a while.\n2.  Execute the Payload Estimation after power cycle.\n3.  If the alarm is still issued, document the events that led to the error, and contact your FANUC technical\nrepresentative.",
    "185": "SRVO-185 Data is for other group\nCause:  This is an error internal to the system.\nRemedy:\n1.  Execute the Payload Estimation after power cycle.\n2.  If the alarm is still issued, document the events that led to the error, and contact your FANUC technical\nrepresentative.",
    "186": "SRVO-186 Needed Data has not been got\nCause:  This is an error internal to the system.\nRemedy:\n1.  Execute the Payload Estimation after power cycle.\n2.  If the alarm is still issued document the events that led to the error, and contact your FANUC technical\nrepresentative.",
    "187": "SRVO-187 Need specfing Mass\nCause:  Estimating the load information of this type requires specifying the mass of the load.\nRemedy:  Specify the mass of the load before Payload Estimation.",
    "188": "SRVO-188 Memory is lacking\nCause:  The system could not allocate the enough memory area on the DRAM for Payload Estimation.\nRemedy:\n1.  Execute the Payload Estimation after power cycle.\n2.  If the alarm is still issued, you need to update the memory size of DRAM. Document the events that led to the\nerror, and contact your FANUC technical representative.",
    "191": "SRVO-191 Illegal Joint Speed (G:%d A:%d)\nCause:  The motion command exceeded the specification.\nRemedy:  This is an internal motion error. Document the events that led to the error, and contact your FANUC technical\nrepresentative.\nNote: You need to cycle power to release this alarm.",
    "199": "SRVO-199 Controlled Stop\nCause:  A Controlled Stop has been done.\nRemedy:  After this alarm, a Fence open or SVOFF input alarm is detected. See the remedy of those alarms for more\ninformation.",
    "204": "SRVO-204 External(SVEMG abnormal) E-stop\nCause:  The external emergency stop push button was pressed, but the EMERGENCY STOP line was not disconnected.\nRemedy:  Refer to the Controller Maintenance Manual for more information. Note: Need power cycle to release this alarm.",
    "205": "SRVO-205 Fence open(SVEMG abnormal)\nCause:  The fence circuit was opened, but the EMERGENCY STOP line was not disconnected.\nRemedy:  Refer to the Controller Maintenance Manual for more information. Note: Need power cycle to release this alarm.",
    "206": "SRVO-206 Deadman switch (SVEMG abnormal)\nCause:  The teach pendant deadman switch was released while the teach pendant was enabled, but the EMERGENCY STOP\nline was not disconnected.\nRemedy:  Refer to the Controller Maintenance Manual for more information. Note: Need power cycle to release this alarm.",
    "207": "SRVO-207 TP switch abnormal or Door open\nCause:  The EMERGENCY STOP line has been disconnected although there is no emergency stop factor.\nRemedy:\n1.  Replace the teach pendant.\n2.  Replace the teach pendant cable.\n3.  Replace the operator’s panel.\n4.  Replace the E-Stop unit.\n5.  Replace the servo amplifier.",
    "209": "SRVO-209 Robot-%d SVEMG abnormal\nCause:  An abnormality of the emergency stop line of robot 2 or later was detected.\nRemedy:\n1.  Replace the E-Stop unit of robot 2 or later.\n2.  Replace the servo amplifier of robot 2 or later.\n3.  Document the events that led to the error, and contact your FANUC technical representative.",
    "211": "SRVO-211 TP OFF in T1,T2\nCause:  The teach pendant was disabled while the mode switch was set in the T1 or T2 position and robot 1 and 2 were\ndisconnected. Alternatively, there is a failure in the hardware.\nRemedy:\n1.  Set the teach pendant enable/disable switch to on, and press RESET.\n2.  Document the events that led to the error, and contact your FANUC technical representative.",
    "213": "SRVO-213 E-STOP Board FUSE2 blown\nCause:  A fuse (FUSE2) on the emergency stop board has blown.\nRemedy:  Replace the fuse (FUSE2) on the emergency stop board or the emergency stop board. Refer to the Controller\nMaintenance Manual for more information.",
    "214": "SRVO-214 6ch amplifier fuse blown(R:%d)\nCause:  The fuse on the servo amplifier has blown. Number in the bracket indicates which 6ch amplifier is abnormal.\nRemedy:  Replace the fuse on the servo amplifier. Refer to the Controller Maintenance Manual for more information.",
    "215": "SRVO-215 Brake Unit fuse blown(R:%d)\nCause:  The fuse FUSE1 on the brake unit has blown. Number in the bracket indicates which 6ch amplifier the brake unit is\nconnected.\nRemedy:  Replace this fuse after replacing the brake cable because it might be defective. (If this fuse has blown, it may be\ncaused by some defect of the brake cable.)",
    "216": "SRVO-216 OVC(total) (%d)\nCause:  The current flowing through the robot cable has exceeded its limit. Number in the bracket indicates which amplifier\nnumber is abnormal.\nRemedy:\n1.  Slow the motion of the robot where possible. Check the robot operation conditions. If the robot is used with a\ncondition exceeding the duty or load weight robot rating, reduce the load condition value to the specification\nrange.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "217": "SRVO-217 E-STOP Board not found\nCause:  The emergency stop board is not found when the controller power is turned on.",
    "220": "SRVO-220 SDI fuse blown\nCause: The fuse for SDI has blown.\nRemedy: Replace the fuse on the main board or main board itself. Refer to the Mate Controller Maintenance Manual for more information.",
    "221": "SRVO-221 Lack of DSP (G:%d A:%d)\nCause:  A controlled axis card corresponding to the set number of axes ($SCR_GRP.$AXISORDER) is not mounted.\nRemedy:\n1.  Check whether the set number of axes is valid. If the number is invalid, set the correct number.\n2.  Replace the axis control card with a card corresponding to the set number of axes.",
    "222": "SRVO-222 Lack of Amp (Amp:%d)\nCause:  The servo amplifiers were not found at the power up sequence.\nRemedy:\n1.  When any LED on the servo amplifier does not light with the power supply of the controller turned on, the power\nis not supplied to the servo amplifier. Confirm whether there is neither disconnecting nor loosening in each\nconnector on the servo amplifier and the E-Stop unit.\n2.  Turn off the power of the controller, disconnect the Pulsecoder cable JF1,JF2 from the servo amplifier and turn\non the power of the controller again. If this alarm does not occur, the Pulsecoder cable may have ground fault.\n(The LED of the servo amplifier may display blinking - in this case.)\n3.  Check whether the servo amplifier for auxiliary axis for R-30iA is connected to R-30iB controller.\n4.  Replace the servo amplifier for auxiliary axis.\n5.  Replace the 6-axis servo amplifier.\n6.  Replace the optical fiber cable.\n7.  Replace the servo card or the auxiliary axis servo card.",
    "223": "SRVO-223 DSP dry run (%d,%d)\nCause:  A servo DSP initialization failure occurred due to hardware failure or wrong software setting. Then, the software\nentered DSP dry run mode. The first number indicates the cause of the failure. The second number is extra\ninformation.\nRemedy:  Perform an action according to the first number that is displayed in the alarm message.\n1: This is a warning due to $SCR.$STARTUP_CND=12.\n2,3,4,7: Replace a servo card.\n5: Invalid ATR setting. Software axis config (FSSB line number, hardware start axis number, amplifier number, and\namplifier type) might be wrong.\n6: SRVO-180 occurs simultaneously. Controllable axis does not exist on any group. Execute aux axis setting to add\naxis at controlled start.\n8,10: SRVO-058 (FSSB init error) occurs simultaneously. Follow the remedy of SRVO-058.\n9: There is no amplifier that is connected to the servo card.\n•  Check the hardware connection.\n•  Check the optical fiber cable.\n•  Check whether the servo am plifier power is supplied.\n•  Check whether the fuse on the servo amplifier has blown.\n•  Replace the optical fiber cable.\n•  Replace the servo amplifier.\n11: Invalid axisorder setting. Non-existing axis number is specified. Software axis config (FSSB line number) might be\nwrong or auxiliary axis board is necessary.\n12: SRVO-059 (Servo amp init error) occurs simultaneously. Follow the remedy of SRVO-059.\n13,14,15: Document the events that led to the error, and contact your FANUC technical representative.",
    "224": "SRVO-224 Slot changed (AuxBrd%d, %d>%d)\nCause:  Hardware slot of the auxiliary axis board has been changed.\nRemedy:  Please verify this change is valid. If this change is due to a simple mistake, please restore the hardware configuration\nto its original condition.",
    "230": "SRVO-230 Chain 1 abnormal %x,%x\nCause:\n1.  A failure occurred in chain 1 (+24V)/chain2(0V) of emergency stop circuit.\n2.  There is a possibility that the specification of the teach pendant is incorrect when occurring immediately after\nturning on of the power supply. For instance, this might occur if the teach pendant of non-RIA/CE specification\nis connected with the controller of the RIA/CE specification.\nRemedy:\n1.  In the above case 2, connect a correct teach pendant.\n2.  Confirm the history of the alarm on the Alarm Log screen. If occurring with either Operator panel E-stop,\nTeach pendant E-stop or Deadman switch released, the emergency stop button is released, and it presses again.\nFor deadman switch, the deadman switch is gripped once and it released again. Chain abnormal state was\nreleased if occurring SRVO-236 Chain failure is repaired. Release the emergency stop button, deadman and\npress RESET.\n3.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.\nAfter these measures, the release operation of chain abnormal state is necessary.\na.  Press the emergency stop button on the teach pendant or operator panel once and release it.\nb.  Press F4 RES_1CH on the Alarm Active screen.\nc. Press RESET.",
    "231": "SRVO-231 Chain 2 abnormal %x,%x\nCause:\n1.  A failure occurred in chain 1 (+24V)/chain2(0V) of emergency stop circuit.\n2.  There is a possibility that the specification of the teach pendant is incorrect when occurring immediately after\nturning on of the power supply. For instance, this might occur if the teach pendant of non-RIA/CE specification\nis connected with the controller of the RIA/CE specification.\nRemedy:  See the description for the SRVO-230 Chain 1 abnormal.",
    "232": "SRVO-232 NTED input\nCause:  The NTED (non-teacher enabling device) was detected.\nRemedy:\n1.  Press the NTED (non-teacher enabling device), and then press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "233": "SRVO-233 TP OFF in T1,T2/Door open\nCause:  The mode switch is set in the T1 or T2 position, and the teach pendant is disabled. Alternatively, the controller door is\nopen. There is also a failure in the hardware.\nRemedy:\n1.  After setting the teach pendant enable/disable switch to on, close the controller door, and press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "235": "SRVO-235 Short term Chain abnormal\nCause:  A temporary chain failure was detected.\nRemedy:\n1.  Press the emergency stop button on the teach pendant or the operator panel again. If occurring SRVO-236 Chain\nfailure is repaired. Release the emergency stop button and press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information. After these\nmeasures, the release operation of chain abnormal state is necessary.\na.  The emergency stop button on the teach pendant or operator panel is pressed once, and released.\nb.  F4 RES_1CH is pressed on the Alarm Active screen.\nc.  The reset button is pressed.",
    "236": "SRVO-236 Chain failure is repaired\nCause:  A chain failure was removed.\nRemedy:  When the system checked for the chain failure again, the chain failure had been removed. Press RESET.",
    "237": "SRVO-237 Cannot reset chain failure\nCause:  An attempt to reset the chain failure failed.\nRemedy:  Refer to the remedy of SRVO-230.",
    "244": "SRVO-244 Chain 1 abnormal(Rbt:%d)\nCause:  An abnormal chain occurred with the robot displayed in ().\nRemedy:  Refer to the Cause and Remedy of SRVO-230.",
    "245": "SRVO-245 Chain 2 abnormal(Rbt:%d)\nCause:  An abnormal chain occurred with the robot displayed in ().\nRemedy:  Refer to the Cause and Remedy of SRVO-230.",
    "246": "SRVO-246 Chain 1 abnormal(EX_robot)\nCause:  An abnormal chain occurred with the robot displayed in ().\nRemedy:  Refer to the Cause and Remedy of SRVO-230.",
    "247": "SRVO-247 Chain 2 abnormal(EX_robot)\nCause:  An abnormal chain occurred with the robot displayed in ().\nRemedy:  Refer to the Cause and Remedy of SRVO-230.",
    "248": "SRVO-248 Deadman switch status abnormal\nCause:  The status of two DIs of DEADMAN switch do not match.\nRemedy:\n1.  Release both deadman switches at once. If SRVO-236 Chain failure is repaired occurred, there is no hardware\nproblem. This alarm could occur when deadman switch is pressed halfway.\n2.  When SRVO-236 does not occur, please replace hardware in following order. - Teach pendant - Cable between\nteach pendant and the emergency stop board - the emergency stop board - Cable between the emergency stop\nboard and main board.\n3.  After measures, the release operation of chain abnormal state is necessary.\n•  The emergency stop button on the teach pendant or operator panel is pressed once, and released.\n•  F4 RES_1CH is pressed on the Alarm Active screen.\n•  The reset button is pressed.",
    "251": "SRVO-251 DB relay abnormal(G:%d A:%d)\nCause:  An abnormality was detected in the internal relay (DB relay) of the servo amplifier.\nRemedy:  Replace the servo amplifier.",
    "252": "SRVO-252 Current detect abnl(G:%d A:%d)\nCause:  An abnormality was detected in the current detection circuit inside the servo amplifier.\nRemedy:  Replace the servo amplifier.",
    "253": "SRVO-253 Amp internal over heat(G:%d A:%d)\nCause:  An overheat was detected inside the servo amplifier.\nRemedy:  Check that the cooling fan is working properly, or replace the servo amplifier.",
    "266": "SRVO-266 FENCE1 status abnormal\nCause:  The fence circuit is abnormal.\nRemedy:  There is miswiring of the FENCE signal. Refer to the Controller Maintenance Manual for more information. After\nthese measures, the release operation of chain abnormal state is necessary.\n1.  The emergency stop button on the teach pendant or operator panel is pressed once, and released.\n2.  F4 RES_1CH is pressed on the Alarm Active screen.\n3.  The reset button is pressed.",
    "267": "SRVO-267 FENCE2 status abnormal\nCause:  The fence circuit is abnormal.\nRemedy:  Refer to the Cause and Remedy of SRVO-266.",
    "268": "SRVO-268 SVOFF1 status abnormal\nCause:  The SVOFF circuit is abnormal.\nRemedy:  There is miswiring of the SVOFF signal. Refer to the Controller Maintenance Manual for more information. After\nthese measures, the release operation of chain abnormal state is necessary.\n1.  The emergency stop button on the teach pendant or operator panel is pressed once, and released.",
    "269": "SRVO-269 SVOFF2 status abnormal\nCause:  The SVOFF circuit is abnormal.\nRemedy:  Refer to the Cause and Remedy of SRVO-268.",
    "270": "SRVO-270 EXEMG1 status abnormal\nCause:  The EXEMG circuit is abnormal.\nRemedy:  The EXEMG signal is miswired. Refer to the Controller Maintenance Manual for more information. After these\nmeasures, the release operation of chain abnormal state is necessary.\n1.  The emergency stop button on the teach pendant or operator panel is pressed once, and released.\n2.  F4 RES_1CH is pressed on the Alarm Active screen.\n3.  The reset button is pressed.",
    "271": "SRVO-271 EXEMG2 status abnormal\nCause:  The EXEMG circuit is abnormal.\nRemedy:  Refer to the Cause and Remedy of SRVO-270.",
    "274": "SRVO-274 NTED1 status abnormal\nCause:  The NTED circuit is abnormal.\nRemedy:  The NTED signal is miswired. Refer to the Controller Maintenance Manual for more information. After these\nmeasures, the release operation of chain abnormal state is necessary.\n1.  The emergency stop button on the teach pendant or operator panel is pressed once, and released.\n2.  F4 RES_1CH is pressed on the Alarm Active screen.\n3.  The reset button is pressed.",
    "275": "SRVO-275 NTED2 status abnormal\nCause:  The NTED circuit is abnormal.\nRemedy:  Refer to the Cause and Remedy of SRVO-274.",
    "276": "SRVO-276 Disable on T2 mode\nCause:  The robot cannot operate in T2 mode.\nRemedy:  Set the mode switch to the T1 or AUTO position.",
    "277": "SRVO-277 Panel E-stop(SVEMG abnormal)\nCause:  The emergency stop line was not disconnected although the emergency stop button on the operators panel was\npressed.\nRemedy:\n1.  Release the operator panel EMERGENCY STOP button, then cycle controller power again.\n2.  When the operator panel EMERGENCY STOP button is pushed again, and this alarm occurs again, refer to the\nController Maintenance Manual for more information.\nNote:\n1.  Need power cycle to release this alarm.\n2.  This alarm might occur when the emergency stop button is pushed too slowly. In this case, the above remedy 2 is\nunnecessary.",
    "278": "SRVO-278 TP E-stop(SVEMG abnormal)\nCause:  The EMERGENCY STOP button on the Teach Pendant was pressed, but the EMERGENCY STOP line was not\ndisconnected.\nRemedy:\n1.  Release the TP EMERGENCY STOP button, then the controller power cycle again.\n2.  When the TP EMERGENCY STOP button is pushed again, and this alarm occurs again, refer to the Controller\nMaintenance Manual for more information.\nNote:\n1.  Need power cycle to release this alarm.\n2.  This alarm might occur when the emergency stop button is pushed slowly. In this case, the above remedy 2 is\nunnecessary.",
    "280": "SRVO-280 SVOFF input\nCause:  The SVOFF (servo off signal) was input.\nRemedy:\n1.  Find out what caused the SVOFF to be input, and remove the cause. Press RESET.\n2.  If this alarm cannot be reset, refer to the Controller Maintenance Manual for more information.",
    "290": "SRVO-290 DClink HC alarm(G:%d A:%d)\nCause:  The DC link current of the servo amplifier is abnormally high.\nRemedy:  Refer to the remedy of SRVO-045.",
    "291": "SRVO-291 IPM over heat (G:%d A:%d)\nCause:  It was detected that the IPM element in the amplifier had overheated.\nRemedy:\n1.  Check whether the amplifier fan rotates normally.\n2.  Decrease the duty cycle of operation.\n3.  If this symptom occurs frequently, replace the amplifier.\nRefer to the Controller Maintenance Manual for more information.",
    "292": "SRVO-292 EXT.FAN alarm (G:%d A:%d)\nCause:  The external fan for the servo amplifier (α iSV) is faulty.\nRemedy:  Replace the cooling fan.",
    "293": "SRVO-293 HCAL (PS) alarm(G:%d A:%d)\nCause:  The three-phase input power supply is abnormal or the Power Supply (α iPS) is faulty.\nRemedy:\n1.  Check the three-phase input power supply.\n2.  Replace the Power Supply (α iPS).",
    "294": "SRVO-294 EXT.FAN(PS) alarm(G:%d A:%d)\nCause:  The external fan for the Power Supply (α iPS) is faulty.\nRemedy:  Replace the external fan.",
    "295": "SRVO-295 AMP com error (G:%d A:%d)\nCause:  A communication error occurred in the 6-axis amplifier or between the Power Supply (α iPS) and the servo amplifier.\nRemedy:\n1.  Replace the 6-axis amplifier.\n2.  Replace the cable for communication the Power Supply (α iPS) and servo amplifier.\n3.  Replace the Poewr Supply (α iPS).\n4.  Replace the servo amplifier (α iSV).",
    "296": "SRVO-296 Excess regeneration1(PS) (G:%d A:%d)\nCause:\n1.  The cooling fan for the regenerative resistance of the Power Supply (α iPS) stops.\n2.  The use condition is too hard for the regenerative resistance of the Power Supply (α iPS).\nRemedy:\n1.  Check the fan for the regenerative resistor is working. If it stops, replace the fan.\n2.  Lower the teaching speed in the program.\n3.  Replace the Power Supply (α iPS).",
    "297": "SRVO-297 Improper input power(PS) (G:%d A:%d)\nCause:  Three-phase input power supply voltage is low.\nRemedy:\n1.  Check the voltage of the three-phase input power of the controller.\n2.  Replace the Power Supply (α iPS).\n3.  Replace the 6-axis amplifier.\n4.  Replace the E-stop unit.\nRefer to the Controller Maintenance Manual for more information.",
    "298": "SRVO-298 SRVO velocity alm(G:%d A:%d)\nCause:  The speed calculated in the servo software is abnormal.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.\nNote: Need power cycle to release this alarm.",
    "300": "SRVO-300 Hand broken/HBK disabled\nCause:  When the HBK setting is disabled, a hand-broken signal was detected.\nRemedy:  To remove the alarm condition, press RESET. Check whether the hand-broken signal circuit is connected to the robot.\nIf the circuit is connected to the robot, enable the hand-broken setting.",
    "301": "SRVO-301 Hand broken/HBK dsbl(G:%d)\nCause:  When the HBK setting is disabled, a hand-broken signal was detected.\nRemedy:  Refer to the Cause and Remedy of SRVO-300.",
    "302": "SRVO-302 Set Hand broken to ENABLE\nCause:  When the HBK setting is disabled, a hand-broken signal was detected.\nRemedy:  To remove the alarm condition, press RESET. Check whether the hand-broken signal circuit is connected to the robot.\nIf the circuit is connected to the robot, enable the hand-broken setting.",
    "303": "SRVO-303 Set HBK to ENABLE(G:%d)\nCause:  When the HBK setting is disabled, a hand-broken signal was detected.\nRemedy:  Refer to the Cause and Remedy of SRVO-302.",
    "305": "SRVO-305 Unit Change(G%d,%s)\nCause:  The robot model was changed.\nRemedy:  Turn off and on the controller power supply.",
    "306": "SRVO-306 CPU ready Timeout (Rbt:%d)\nCause:  Displayed robot arm did not start up within a fixed time.\nRemedy:  Please confirm the robot arm is displayed with warning message.",
    "310": "SRVO-310 ABC Unexpected Motion(G:%d)\nCause:  A current robot position that software calculates is abnormal.\nRemedy:\n1.  Mastering data could be incorrect. Confirm whether incorrect backup data is restored or mastering has been\nexecuted at the wrong position. In that case, execute mastering.\n2.  Document the events that led to the error, and contact your FANUC technical representative.",
    "315": "SRVO-315 MPDT failed(G:%d A:%d)\nCause:  Magnetic Phase Detection (MPDT) for 3rd party motor failed. Probable causes are:\n1.  The motor power cable is disconnected.\n2.  The axis falls down by the gravity during performing of MPDT.\n3.  Other alarm occurs during performing of MPDT.\n4.  The motor cannot move due to large load or friction.\nRemedy:\n1.  Check whether the motor power cable is connected correctly.\n2.  MPDT cannot be applied for gravity axis. If possible, change the posture.\n3.  Remove the reason of other alarms which occurred at same time.\n4.  Check whether the axis which requires to perform MPDT does not contact with any object.\n5.  Confirm that brake is not engaged.",
    "316": "SRVO-316 MPDT time is up(G:%d A:%d)\nCause:  Magnetic Phase Detection (MPDT) process time is up. Probable causes are:\n1.  The axis fell down because of gravity during performing of MPDT.\n2.  Other alarms occurred during performing of MPDT.\nRemedy:\n1.  MPDT cannot be applied for gravity axis. If possible, change the posture.\n2.  Remove the reason of other alarm which occurred at the same time.",
    "317": "SRVO-317 MPDT cannot start(Machine Lock)\nCause:  Magnetic Phase Detection (MPDT) process cannot start because machine lock is enabled for that group.\nRemedy:  Disable machine lock for that group.",
    "318": "SRVO-318 MPDT cannot start(SRDY Off)\nCause:  Magnetic Phase Detection (MPDT) process cannot start because servo ready (SRDY) is off.\nRemedy:  Remove the reason of servo ready (SRDY) off.",
    "323": "SRVO-323 Torque limit (G%d A%d L%d)\nCause:  Torque limit reached. The third number indicates the line number of the TP program.\nRemedy:  Modify TP programd to be less aggressive.",
    "324": "SRVO-324 Disturbance excess(G%d A%d L%d)\nCause:  Disturbance estimated in the software exceeds the threshold value. There is possibility that SRVO-050 occurs when\nthe robot runs leaving this warning.\nRemedy:\n1.  Check whether the payload (mass, center of gravity, and inertia) are set correctly.\n2.  Check whether the applied load exceed the rating. If so, reduce the applied load.\n3.  If this alarm occurs when the robot is used after long time interval or when the temperature is very low, run the\nrobot with low speed for a while before running with normal speed.",
    "325": "SRVO-325 Alarm %d\nCause:  Varies by alarm number:\nAlarm 101: fail to send command to MPC\nAlarm 102: fail to send command to DSP (buffer full)\nAlarm 103: fail to send command to FLTR\nAlarm 105: illegal axis number\nAlarm 106: CPMCWT was OFF when first command\nAlarm 107: NOCPMC is detected\nAlarm 108: ANACC is detected\nAlarm 109: limit error is detected\nRemedy:  Please turn on servo again.",
    "326": "SRVO-326 Abnormal Mcmd (G:%d A:%d)\nCause:  The different between motion command and machine pulse exceeded specified threshold .\nRemedy:  Internal motion error. Document the events that led to the error, and contact your FANUC technical representative.",
    "330": "SRVO-330 Retry count err(G:%d A:%d)\nCause:  The retry count of the Pulsecoder exceeded a limit value of $PLS_ER_LIM when $PLS_ER_CHK=1.\nRemedy:  It is likely that the Pulsecoder has malfunctioned due to noise or the Pulsecoder is abnormal.\n1.  Check if there exists a noise source near the Pulsecoder.\n2.  Replace the Pulsecoder.\n3.  Replace the Pulsecoder cable.\n4.  Replace the servo amplifier.\n5.  If the error is not cleared with the above remedies, refer to the Cause and Remedy of SRVO-068(DTERR).",
    "331": "SRVO-331 FB comp cnt err(G:%d A:%d)\nCause:  The position feedback compensation count of the Pulsecoder exceeded a limit value of $PLS_CMP_LIM when\n$PLS_ER_CHK=1.\nRemedy:  It is likely that the Pulsecoder has malfunctioned due to noise or the Pulsecoder is abnormal.\n1.  Check if there exists a noise source near the Pulsecoder.\n2.  Replace the Pulsecoder.\n3.  Replace the Pulsecoder cable.\n4.  Replace the servo amplifier.\n5.  If the error is not cleared with the above remedies, refer to the Cause and Remedy of SRVO-068(DTERR).",
    "332": "SRVO-332 Power off to reset CMAL\nCause:  Power off is required to reset the CMAL alarm.",
    "333": "SRVO-333 Power off to reset\nCause:  Power off is required.\nRemedy:  Turn off/on the controller.",
    "335": "SRVO-335 DCS OFFCHK alarm %x,%x\nCause:  A failure was detected in the safety signal input circuit.\nRemedy:  Replace the emergency stop board.\nIn case of B-cabinet, replace the optional safety I/O board.",
    "336": "SRVO-336 DCS RAMCHK alarm %x,%x\nCause:  DRAM failure is detected.\nRemedy:  Check the other alarms for more information.\nReplace the CPU card. Replace the main board.",
    "337": "SRVO-337 DCS PRMCHK alarm %x,%x\nCause:  DCS parameter error is detected.\nWhen an image restore is done and ‘No’ is selected for initialize DCS parameter, if the previous DCS parameters are\ndifferent from what is in the image file, this alarm occurs.\nRemedy:\n1.  Do an APPLY of the DCS parameters if an image restore was done.\n2.  If power down occurred while DCS parameters were being changed, set the DCS parameters again.\n3.  Load backup files.\n4.  Replace main board, CPU card, FROM/SRAM module.",
    "338": "SRVO-338 DCS FLOW alarm %x,%x\nCause:  DCS process error is detected.\nRemedy:  Check the other alarms for more information.",
    "339": "SRVO-339 DCS MISC alarm %x,%x\nCause:  DCS process error is detected.\nRemedy:  Check the other alarms for more information.",
    "340": "SRVO-340 DCS T1 TCP speed(G%d) %x,%x\nCause:  The TCP speed exceeds 250mm/sec in T1 mode.\nRemedy:  Make the override lower.",
    "341": "SRVO-341 DCS T1 flange speed(G%d) %x,%x\nCause:  The flange speed exceeds 250mm/sec in T1 mode.\nRemedy:  Make the override lower.",
    "344": "SRVO-344 DCS GRP alarm(G%d) %x,%x\nCause:  A software internal error has occurred.\nRemedy:  Check the other alarms for more information.",
    "347": "SRVO-347 DCS AXS alarm(G%d,A%d) %x,%x\nCause:  A software internal error has occurred.\nRemedy:  Check the other alarms for more information.",
    "348": "SRVO-348 DCS MCC OFF alarm %x,%x\nCause:  A command was issued to turn off the magnetic contactor, but the magnetic contactor was not turned off.\nRemedy:\n1.  Replace the E-Stop unit.\n2.  If a signal is connected to the E-Stop unit CRMA74, check whether there is a problem in the connection\ndestination.",
    "349": "SRVO-349 DCS MCC ON alarm %x,%x\nCause:  A command was issued to turn on the magnetic contactor, but the magnetic contactor was not turned on.\nRemedy:\n1.  Replace the E-Stop unit.\n2.  Replace the servo amplifier.",
    "350": "SRVO-350 DCS CPU alarm %x,%x\nCause:  An error occurred in the RAM self test.\nRemedy:  Replace the CPU card or main board.",
    "351": "SRVO-351 DCS CRC alarm %x,%x\nCause:  An error occurred in the safety software CRC test.\nRemedy:  Load the system software or replace the FROM/SRAM module.",
    "352": "SRVO-352 DCS COUNT1 alarm %x,%x\nCause:  The safety software does not run with the proper timing.\nRemedy:  Check the other alarms for more information.",
    "353": "SRVO-353 DCS COUNT2 alarm %x,%x\nCause:  The safety software does not run with the proper timing.\nRemedy:  Check the other alarms for more information.",
    "354": "SRVO-354 DCS DICHK alarm %x,%x\nCause:  The safety software does not run with the proper timing.\nRemedy:  Check the other alarms for more information.",
    "355": "SRVO-355 DCS ITP_TIME alarm %x,%x\nCause:  The safety software does not run with the proper timing.\nRemedy:  Check the other alarms for more information.",
    "356": "SRVO-356 DCS ITP_SCAN alarm %x,%x\nCause:  The safety software does not run with the proper timing.\nRemedy:  Check the other alarms for more information.",
    "357": "SRVO-357 DCS ENABLED alarm %x,%x\nCause:\n1.  Cartesian Position Check, Cartesian Speed Check or T1 Mode Speed Check is enabled for a motion group that\ndoes not exist.\n2.  Joint Position Check or Joint Speed Check is enabled for an axis that does not exist.\n3.  Joint Position Check or Joint Speed Check is enabled for an axis that is excluded.\n4.  Cartesian Position Check, Cartesian Speed Check or T1 Mode Speed Check is enabled for a motion group that\nhas an excluded axis that is not an auxiliary extended axis.\nRemedy:  Disable Joint Position Check, Joint Speed Check, Cartesian Position Check, Cartesian Speed Check or T1 Mode Speed\nCheck.",
    "358": "SRVO-358 DCS INVPRM alarm %x,%x\nCause:  Invalid data is set in the DCS parameters.\nRemedy:  Check DCS setting. Load backup files that were saved when the parameters were correct.",
    "359": "SRVO-359 DCS SYSTEM alarm %x,%x\nCause:\n1.  When config Signature Date/Time is ACTUAL in DCS CIP Safety menu, System clock setting is invalid. (Valid\nyear is 2004-2150.)\n2.  Invalid data is set in the DCS parameters.\nRemedy:\n1.  Set Config Signature Date/Time to FIXED, or set correct date/time to system clock.\n2.  Check DCS setting. Load backup files that were saved when the parameters were correct.",
    "360": "SRVO-360 DCS CC_TCP alarm(G%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "361": "SRVO-361 DCS CC_FP alarm(G%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "362": "SRVO-362 DCS CC_TCPS alarm(G%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "363": "SRVO-363 DCS CC_FPS alarm(G%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "364": "SRVO-364 DCS PRMCRC alarm(G%d) %x,%x\nCause:  This robot model is not supported.\nRemedy:  Delete ‘DCS Position/Speed Check function’ option.\nThis alarm can be cleared by setting $DCS_CFG.$SYS_PARAM to 1, but in this case, Position/Speed Check function\ncan not be used.",
    "365": "SRVO-365 DCS FB_CMP alarm(G%d,A%d) %x,%x\nCause:  Difference between position command and position feedback exceeds position tolerance. The same cause as\n‘SRVO-023 Stop error excess’ or ‘SRVO-024 Move error excess’ is expected.\nRemedy:  Please refer the Remedy of SRVO-023.\nCheck the setting data displayed in the DCS robot setup menu.",
    "366": "SRVO-366 DCS FB_INFO alarm(G%d,A%d) %x,%x\nCause:  Invalid data is set in DCS parameter for axis number.\nRemedy:  Check the setting data displayed in the DCS robot setup menu.",
    "367": "SRVO-367 DCS CC_JPOS alarm(G%d,A%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "368": "SRVO-368 DCS CC_JSPD alarm(G%d,A%d) %x,%x\nCause:  Results of 2 CPU are different.\nRemedy:  Check the other alarms for more information.",
    "370": "SRVO-370 SVON1 status abnormal\nCause:  A chain alarm was detected with the emergency stop board internal signal (SVON).\nRemedy:  Replace the emergency stop board.",
    "371": "SRVO-371 SVON2 status abnormal\nCause:  A chain alarm was detected with the emergency stop board internal signal (SVON).\nRemedy:  Replace the emergency stop board.",
    "372": "SRVO-372 OPEMG1 status abnormal\nCause:  A chain alarm was detected with the emergency stop switch on the operators panel.\nRemedy:\n1.  Replace the emergency stop board.\n2.  Replace the teach pendant cable.\n3.  Replace the teach pendant.\n4.  Replace the emergency stop button on the operators panel.",
    "373": "SRVO-373 OPEMG2 status abnormal\nCause:  A chain alarm was detected with the emergency stop switch on the operators panel.",
    "374": "SRVO-374 MODE11 status abnormal\nCause:  A chain alarm was detected with the mode switch signal.\nRemedy:\n1.  Check the mode switch and its cable. Replace them if a defect is found.\n2.  Replace the emergency stop board.",
    "375": "SRVO-375 MODE12 status abnormal\nCause:  A chain alarm was detected with the mode switch signal.\nRemedy:\n1.  Check the mode switch and its cable. Replace them if a defect is found.\n2.  Replace the emergency stop board.",
    "376": "SRVO-376 MODE21 status abnormal\nCause:  A chain alarm was detected with the mode switch signal.\nRemedy:\n1.  Check the mode switch and its cable. Replace them if a defect is found.\n2.  Replace the emergency stop board.",
    "377": "SRVO-377 MODE22 status abnormal\nCause:  A chain alarm was detected with the mode switch signal.\nRemedy:\n1.  Check the mode switch and its cable. Replace them if a defect is found.\n2.  Replace the emergency stop board.",
    "378": "SRVO-378 SFDIxx status abnormal\nCause:  A chain alarm was detected with the SFDI signal. xx shows signal name.\nRemedy:\n1.  Check whether the circuitry connected to the dual input signal (SFDI) is faulty.\n2.  Check whether the timing of the dual input signal (SFDI) satisfies the timing specification.\n3.  In case of B-cabinet, replace the optional safety I/O board.\n4.  Replace the emergency stop board.",
    "386": "SRVO-386 Softfloat stroke lim(G:%d)\nCause:  Certain axes reached stroke limit.\nRemedy:  Use soft float with a wide margin.",
    "387": "SRVO-387 Softfloat impossible(G:%d)\nCause:  The position or schedule is not proper.\nRemedy:  Use soft float in the proper position and schedule.",
    "388": "SRVO-388 Softfloat singularity(G:%d\nCause:  Certain axes reached singularity.\nRemedy:  Use soft float with a wide margin.",
    "389": "SRVO-389 Start diag data recording.\nCause:  Beginning to record diagnostic data.\nRemedy:  N/A.",
    "390": "SRVO-390 End diag data recording.\nCause:  Diagnostic data recording is finished.\nRemedy:  N/A.",
    "391": "SRVO-391 Start diag data saving.\nCause:  Beginning to save diagnostic data.\nRemedy:  N/A.",
    "392": "SRVO-392 End diag data saving.\nCause:  Diagnostic data has been saved.\nRemedy:  N/A.",
    "393": "SRVO-393 Other diagnosis data is being recorded.\nCause:  Other diagnosis data is being recorded.\nRemedy:  Wait until the recording is finished.",
    "394": "SRVO-394 Reducer Abnormal(Gi,Aj)\nCause:  iRDiagnostics - Robot Condition Detection Function has detected abnormality. Reducer may be degraded.\nRemedy:  Check out the mechanical part of corresponding axis.",
    "399": "SRVO-399 TorsionCompException (ID:%d\nCause:  This is a message to notify that Torsion Compensation failed to execute. This message is shown by Tool Torsion\nCompensation option etc.\nWhen ID is 0: robot is not mastered or not calibrated yet.\nWhen ID is 1: an invalid schedule number is specified.\nWhen ID is 2: an invalid tool number is specified in current schedule.\nWhen ID is 3 or 4: direction is not defined.(in schedule to compensate along the direction defined by TCP velocity\nvector)\nRemedy:  When ID is 0: master and calibrate the robot.\nWhen ID is 1: specify valid schedule number.\nWhen ID is 2: specify valid tool number in current schedule.\nWhen ID is 3 or 4: in these schedules, start compensation while TCP is moving.",
    "401": "SRVO-401 CIP Safety comm. error %x,%x\nCause:  CIP Safety communication error occurs.\nRemedy:  Check CIP Safety connection. Please set CIP Safety to bypass in DCS screen when safety PLC is not available but\nrobot must move in standalone mode.",
    "402": "SRVO-402 DCS Cart. pos. limit(%d,G%d,M%d) %02x\nCause:  Cartesian Position Check function detected that a model is out of a safe zone.\nThe first value : Cartesian Position Check No.\nG : Group number\nM : User model number (0: Robot model)\nRemedy:  If the robot is actually out of thesafe zone, press SHIFT key and RESET key, and jog the robot to the safe zone.",
    "403": "SRVO-403 DCS Cart. speed limit(%d,G%d) %02x\nCause:  Cartesian Speed Check function detected over speed.\nThe first value : Cartesian Speed Check No.\nG : Group number\nRemedy:  Decrease robot speed.",
    "404": "SRVO-404 DCS Joint pos. limit(%d,G%d,A%d) %02x\nCause:  Joint Position Check function detected that an axis is out of a safe zone.\nThe first value : Joint Position Check No.\nG : Group number\nA : Axis number\nRemedy:  If the robot is actually out of the safe zone, press SHIFT key and RESET key, and jog the robot to the safe zone.",
    "405": "SRVO-405 DCS Joint speed limit(%d,G%d,A%d) %02x\nCause:  Joint Speed Check function detected over speed.\nThe first value : Joint Speed Check No.",
    "406": "SRVO-406 DCS SSO SVOFF input %x,%x\nCause:  SSO[1:C_SVOFF] is OFF.\nRemedy:  Check Safe I/O connect setting.",
    "407": "SRVO-407 DCS SSO Fence Open %x,%x\nCause:  SSO[2:C_FENCE] is OFF.\nRemedy:  Check Safe I/O connect setting.",
    "408": "SRVO-408 DCS SSO Ext Emergency Stop %x,%x\nCause:  SSO[3:C_EXEMG] is OFF.\nRemedy:  Check Safe I/O connect setting.",
    "409": "SRVO-409 DCS SSO Servo Disconnect %x,%x\nCause:  SSO[4:C_SVOFF] is OFF.\nRemedy:  Check Safe I/O connect setting.",
    "410": "SRVO-410 DCS SSO NTED input %x,%x\nCause:  SSO[5:C_NTED] is OFF.\nRemedy:  Check Safe I/O connect setting.",
    "411": "SRVO-411 DCS invalid mode %x,%x\nCause:  Invalid mode.\nRemedy:  Select AUTO, T1 or T2.",
    "412": "SRVO-412 DCS COUNT3 alarm %x,%x\nCause:  DCS servo on process is stopped.\nRemedy:  Check the other alarms for more information.",
    "413": "SRVO-413 DCS CC_SAFEIO alarm %x,%x\nCause:  Results of Safe I/O process by 2 CPU are different.\nThis alarm sometimes occur when the safety input signals on the emergency stop board and Safe I/O board such as\nExternal E-STOP or SFDI is changed repeatedly in the very short time.\nRemedy:  Check the connection of the safety input signals on emergency stop board and Safe I/O board.\nCheck the other alarms for more information.",
    "414": "SRVO-414 DCS WORK CRC alarm %x,%x\nCause:  DRAM failure is detected.\nRemedy:  Check the other alarms for more information.\nReplace CPU card. Replace main board.",
    "415": "SRVO-415 DCS Invalid tool (G%d) %x,%x\nCause:\n1.  Selected DCS tool frame number is not defined.\n2.  Verify I/O of DCS tool frame is not set in the selected DCS tool frame.\nRemedy:  Check DCS TCP setting.",
    "416": "SRVO-416 DCS Tool mismatch (G%d) %x,%x\nCause:  All Verify I/O of DCS tool frame are OFF or two or more Verify I/O are ON for more than 1sec.\nRemedy:  Check Verify I/O status.",
    "417": "SRVO-417 DCS APSP_C alarm(G%d) %x,%x\nCause:  Invalid DCS approach speed check parameter for Cartesian position check.\nRemedy:  Check DCS approach speed check parameter.",
    "418": "SRVO-418 DCS APSP_J alarm(G%d,A%d) %x,%x\nCause:  Invalid DCS approach speed check parameter for Joint position check.\nRemedy:  Check DCS approach speed check parameter.",
    "419": "SRVO-419 DCS PROFIsafe comm. error %x,%x\nCause:  PROFINET Safety communication error occurs.\nRemedy:  Check PROFINET Safety connection. Please set PROFINET Safety to bypass in DCS screen when safety PLC is not\navailable but robot must move in standalone mode.",
    "421": "SRVO-421 Jnt phs not calibrated(G%d)\nCause:  $DMR_GRP.$MASTER_DONE is not ready to be set to TRUE because Universal Joint phase calibration data is not\nset.\nRemedy:  When you enter the mastering data via direct entry, enter Universal Joint phase calibration data and set\n$DMR_M3_GRP.$MASTER2_ENB = TRUE first. After that, set $DMR_GRP.$MASTER_DONE = TRUE.",
    "430": "SRVO-430 EQZ Not supported (G:%d)\nCause:  Cannot start equalization because this robot does not support equalization.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.",
    "431": "SRVO-431 EQZ Failed to start (%d)\nCause:  Cannot start equalization for some reason.\nRemedy:  Document the events that led to the error, and contact your FANUC technical representative.",
    "432": "SRVO-432 EQZ is aborted (%d)\nCause:  Equalization was aborted for some reason, HOLD, E-STOP etc.\nRemedy:  Equalization is no longer effective in this motion. If you need to try the Equalization motion again, jog the robot away\nfrom the part, then restart from the line from the line before equalization motion.",
    "433": "SRVO-433 EQZ Dir not selected (G:%d)\nCause:  Equalization Soft Direction is not selected.\nRemedy:  Select Soft Direction via the setup screen.",
    "434": "SRVO-434 EQZ Bad robot posture(G:%d)\nCause:  Equalization is infeasible at this robot posture. Equalization requires that at least one axis among J1, J2 or J3 is\nsensitive to the reaction force from the part. This alarm means there is no sensitive axis.\nRemedy:  If possible, try to change the configuration (U/D, T/B) of the robot.",
    "435": "SRVO-435 EQZ Move Limit (G:%d)\nCause:  Motion with equalization exceeded the Robot Move Limit.\nRemedy:  This alarm indicates an overrun of the robot motion.\n1.  Check if the workpiece exists.\n2.  If this alarm is posted without an obvious overrun, increase Robot Move Limit via the setup menu.",
    "436": "SRVO-436 EQZ Stroke Limit (G:%d,A:%d)\nCause:  Robot reached to its stroke range limit during Equalization motion.\nRemedy:  If possible, try to change the configuration (F/N, U/D, T/B) and turn number of the robot.",
    "437": "SRVO-437 EQZ Singular (G:%d)\nCause:  Robot wrist axis is near the singular point. In other words, J5 is near 0.\nRemedy:  If possible, try to change the configuration (U/D, T/B) of the robot.",
    "438": "SRVO-438 EQZ Speed Excess (G:%d)\nCause:  An instantaneous high speed motion was detected. One possible cause is that robot posture is bad (near SRVO-434\ncondition).\nRemedy:  If possible, try to change the configuration (U/D, T/B) of the robot.",
    "439": "SRVO-439 EQZ Trq not restored(G%dA%d)\nCause:  Ending process of Equalization motion was not normally done.",
    "440": "SRVO-440 EQZ Invalid argument\nCause:  Some arguments to the KAREL is invalid.\nRemedy:  Correct the arguments to the KAREL.",
    "441": "SRVO-441 EQZ GunMntTyp not selected (G:%d)\nCause:  Gun Mount Type is not selected.\nRemedy:  Select Gun Mount Type via the setup screen.",
    "442": "SRVO-442 EQZ FUP time out (G:%d)\nCause:  Robot kept moving when Equlization is about to end.\nRemedy:  Check if the part is firmly fixed.",
    "443": "SRVO-443 EQZ Pos not calculated\nCause:  Destination position of Equalization motion is not calculated.\nRemedy:\n1.  Check if EQTCHPOS is called before EQ start. If not called, add call EQTCHPOS before EQ start.\n2.  If EQTCHPOS causes SRVO-440 or other alarm, eliminate the cause of these alarms first.",
    "444": "SRVO-444 EQZ error (n)\nCause:  An error is detected during Equalization\nRemedy:\nn=1: Document the events that led to the error, and contact your FANUC technical representative.\nn=2: Check if joint position when EQTCHPOS was called is within the motion stroke range.",
    "445": "SRVO-445 EQZ Cant use with softfloat (G:%d)\nCause:  Both Equalization and Softfloat become enabled.\nRemedy:   Modify program or setting so that both Equalization and Softfloat are not enabled at the same time.",
    "448": "SRVO-448 DCS PLSCHK alarm (SFDO%d)\nCause:  The monitored signal of safety output is not OFF even though OFF pulse is output. The signal name that the trouble is\ndetected is displayed after the alarm message.\nRemedy:\n1.  Check the cabling of safety output circuit.\n2.  In case of B-cabinet, replace the optional safety I/O board.\n3.  Replace the emergency stop board.",
    "449": "SRVO-449 DCS DCS DOMON alarm (SFDO%d)\nCause:  The monitored signal of safety ouput is different from the output command. The signal name that the trouble is\ndetected is displayed after the alarm message.\nRemedy:\n1.  Check the cabling of safety output circuit.\n2.  In case of B-cabinet, replace the optional safety I/O board.\n3.  Replace the emergency stop board.",
    "450": "SRVO-450 Drvoff circuit fail (G:%d A:%d)\nCause:  The two drive off inputs are not in the same status.\nRemedy:\n1.  Check the line of the two drive off inputs.\n2.  Replace the servo amplifier.",
    "451": "SRVO-451 Internal S-BUS fail (G:%d A:%d)\nCause:  An error is found in the serial bus communication in the servo amplifier.\nRemedy:  Replace the servo amplifier.",
    "452": "SRVO-452 ROM data failure (G:%d A:%d)\nCause:  An error is found in the ROM data in the servo amplifier.\nRemedy:  Replace the servo amplifier.",
    "453": "SRVO-453 Low volt driver (G:%d A:%d)\nCause:  Driver supply voltage in the servo amplifier is low.\nRemedy:  Replace the servo amplifier.",
    "454": "SRVO-454 CPU BUS failure (G:%d A:%d)\nCause:  An error was found in CPU bus data in the amplifier.\nRemedy:  Replace the servo amplifier.",
    "455": "SRVO-455 CPU watch dog (G:%d A:%d)\nCause:  An error occurred in CPU operation in the amplifier.\nRemedy:  Replace the servo amplifier.",
    "456": "SRVO-456 Ground fault (G:%d A:%d)\nCause:  An error is found in the motor current detection data in the servo amplifier.\nRemedy:  Replace the servo amplifier.",
    "457": "SRVO-457 Ground fault(PS) (G:%d A:%d)\nCause:  Ground fault occurs in the motor power line.\nRemedy:\n1.  Check the ground fault of the motor and the motor power cable.\n2.  Replace the Power Supply (α iPS).\n3.  Replace the servo amplifier.",
    "458": "SRVO-458 Soft thermal(PS) (G:%d A:%d)\nCause:  The root-mean-square current value which is calculated internally by the Power Supply (α iPS) exceeds the maximum\npermissible value. This alarm is issued to protect the Power Supply (α iPS) from damage of thermal destruction.\nProbable cause:\n1. Overload\n2.  External force to the robot\n3.  Disconnection of the brake cable\n4.  Insufficient torque by low voltage of power supply\n5.  Brake failure (includes mis-setting of brake number for auxiliary axis)\n6.  Auxiliary brake unit failure for auxiliary axis\n7.  The Power Supply (α iPS) failure\n8.  The servo amplifier failure\nRemedy:\n1.  Check whether the duty and applied load exceed the rating. If so, reduce the duty or applied load.\n2.  Check whether the robot is pushed or pulled by external force. If so, remove the external force to the robot or\nmodify the taught point.\n3.  Check whether the brake cable/connector are connected correctly.\n4.  Measure the supplied voltage. Then, check whether the voltage is matched to the controller specification.\n5.  Check whether the motor brake is released properly when reset or the robot moves. First of all, check whether the\nsetting of brake number is correct when this alarm occurs on auxiliary axis.\n6.  When this alarm occurs on the auxiliary axis which brake is controlled by the auxiliary brake unit, check the fuse\non the auxiliary brake unit.\n7.  Replace the Power Supply (α iPS).\n8.  Replace the servo amplifier.",
    "459": "SRVO-459 Excess regeneration2(PS) (G:%d A:%d)\nCause:  An error is found in the discharge circuit in the 6-axis amplifier.\nRemedy:  Replace the 6-axis amplifier.",
    "460": "SRVO-460 Illegal parameter(PS) (G:%d A:%d)\nCause:  An error is found in the setting of the parameters in the Power Supply (α iPS) or servo amplifier.",
    "461": "SRVO-461 Hardware error(PS) (G:%d A:%d)\nCause:  An error is found in the circuit in the Power Supply (α iPS) or servo amplifier.\nRemedy:\n1.  Replace the Power Supply (α iPS).\n2.  Replace the servo amplifier."
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  if (global.FanucAlarms) global.FanucAlarms._put("SRVO", data);
})(typeof window !== 'undefined' ? window : globalThis);
